using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace KeyJaya {
public sealed class TriggerRow {public string Key,Value,Raw;public bool Enabled=true,Exact;public TriggerRow Clone(){return (TriggerRow)MemberwiseClone();}}
public sealed class TriggerEntry {
 public string Name,Replacement,Legacy,Plain;public bool Enabled=true,Exact,LegacyOverride,PlainOverride;
 internal bool Dirty,Deleted,New;internal List<TriggerRow> Original=new List<TriggerRow>(),RestoreRows;
 public bool Abbreviation {get{return Core.CtrlOnlyShort(Name);}}
 public TriggerEntry Copy(){var value=(TriggerEntry)MemberwiseClone();value.Original=Original.Select(x=>x.Clone()).ToList();value.RestoreRows=RestoreRows==null?null:RestoreRows.Select(x=>x.Clone()).ToList();return value;}
}
public sealed class TriggerEditorStore {
 readonly string path,header,newline;readonly bool bom;byte[] original;readonly List<TriggerRow> rows;readonly Dictionary<string,List<TriggerRow>> defaults;
 public readonly List<TriggerEntry> Entries;
 static readonly Regex Start=new Regex(@"(?m)^[ \t]*-\s+trigger:\s*([^\r\n]+)",RegexOptions.Compiled);
 public static string Group(string key){int end=key.Length-1;return end>0&&(key[end]=='>'||key[end]=='<'||key[end]=='?')&&Core.CtrlOnlyShort(key.Substring(0,end))?key.Substring(0,end):key;}
 static List<TriggerRow> Parse(string file,out string prefix){var exact=new HashSet<string>(StringComparer.Ordinal);var all=Configuration.Read(file,false,true,exact);var active=Configuration.Read(file);string text=File.ReadAllText(file,Encoding.UTF8);var matches=Start.Matches(text);prefix=matches.Count==0?text:text.Substring(0,matches[0].Index);var result=new List<TriggerRow>();for(int i=0;i<matches.Count;i++){var match=matches[i];string key=Configuration.PlainTriggerKey(Configuration.Decode(match.Groups[1].Value));result.Add(new TriggerRow{Key=key,Value=all[key],Enabled=active.ContainsKey(key),Exact=exact.Contains(key),Raw=text.Substring(match.Index,(i+1<matches.Count?matches[i+1].Index:text.Length)-match.Index)});}return result;}
 static TriggerEntry FromRows(string name,IEnumerable<TriggerRow> source){var records=source.ToList();var unicode=records.FirstOrDefault(x=>x.Key==name+">")??records.FirstOrDefault(x=>x.Key==name);var legacy=records.FirstOrDefault(x=>x.Key==name+"<");var plain=records.FirstOrDefault(x=>x.Key==name+"?");string value=unicode!=null?unicode.Value:legacy!=null?EncodingMap.FromBalaram(legacy.Value):records[0].Value;return new TriggerEntry{Name=name,Replacement=value,Enabled=records.Any(x=>x.Enabled),Exact=records.All(x=>x.Exact),Legacy=legacy==null?EncodingMap.Balaram(value):legacy.Value,Plain=plain==null?EncodingMap.Ascii(value):plain.Value,LegacyOverride=legacy!=null&&legacy.Value!=EncodingMap.Balaram(value),PlainOverride=plain!=null&&plain.Value!=EncodingMap.Ascii(value),Original=records};}
 public TriggerEditorStore(string file,string factoryFile){path=Path.GetFullPath(file);original=File.ReadAllBytes(path);bom=original.Length>=3&&original[0]==239&&original[1]==187&&original[2]==191;string text=File.ReadAllText(path,Encoding.UTF8);newline=text.Contains("\r\n")?"\r\n":"\n";rows=Parse(path,out header);Entries=rows.GroupBy(x=>Group(x.Key),StringComparer.Ordinal).Select(group=>FromRows(group.Key,group)).ToList();defaults=new Dictionary<string,List<TriggerRow>>(StringComparer.Ordinal);if(File.Exists(factoryFile)){string ignored;foreach(var group in Parse(factoryFile,out ignored).GroupBy(x=>Group(x.Key),StringComparer.Ordinal))defaults[group.Key]=group.ToList();}}
 public bool CanRestore(string name){return defaults.ContainsKey(name);}
 public TriggerEntry NewEntry(){return new TriggerEntry{Name="",Replacement="",Legacy="",Plain="",New=true};}
 public static string Normalize(string input,string source="auto"){if(source=="unicode")return input.Normalize(NormalizationForm.FormC);if(source=="balaram")return EncodingMap.FromBalaram(input).Normalize(NormalizationForm.FormC);return Regex.Replace(input,@"[\p{L}\p{M}]+",m=>!EncodingMap.UnambiguousIndic(m.Value)&&m.Value.Any(c=>c!='ñ'&&EncodingMap.IsLegacy(c.ToString()))?EncodingMap.FromBalaram(m.Value):m.Value).Normalize(NormalizationForm.FormC);}
 public void Upsert(TriggerEntry previous,TriggerEntry edited){if(!Core.CtrlOnlyShort(edited.Name)&&(previous==null||previous.Abbreviation||edited.Name!=previous.Name))throw new InvalidDataException("Use letters, numbers, and hyphens for a new abbreviation. Existing literal triggers can keep their names.");if(string.IsNullOrEmpty(edited.Name)||edited.Name.Length>159||edited.Name.Any(char.IsWhiteSpace)||edited.Name.EndsWith(">")||edited.Name.EndsWith("<")||edited.Name.EndsWith("?"))throw new InvalidDataException("Enter an abbreviation without spaces or >, <, ? endings.");if(Entries.Any(x=>x!=previous&&!x.Deleted&&x.Name==edited.Name))throw new InvalidDataException("That trigger already exists. Matching is case-sensitive.");if(edited.Replacement==null||edited.Replacement.Length==0||edited.Replacement.Length>200000)throw new InvalidDataException("Enter replacement text (up to 200,000 characters).");edited.Dirty=true;edited.RestoreRows=null;if(previous==null){edited.New=true;Entries.Add(edited);}else{edited.Original=previous.Original;edited.New=previous.New;Entries[Entries.IndexOf(previous)]=edited;}}
 public void SetEnabled(TriggerEntry entry,bool enabled){if(!entry.Dirty&&!entry.New)entry.RestoreRows=entry.Original.Select(x=>x.Clone()).ToList();entry.Enabled=enabled;entry.Dirty=true;if(entry.RestoreRows!=null)foreach(var row in entry.RestoreRows)row.Enabled=enabled;}
 public void Delete(TriggerEntry entry){entry.Deleted=true;entry.Dirty=true;}
 public TriggerEntry Restore(TriggerEntry entry){List<TriggerRow> factory;if(!defaults.TryGetValue(entry.Name,out factory))throw new InvalidOperationException("This is a custom trigger; it has no built-in replacement.");var restored=FromRows(entry.Name,factory.Select(x=>x.Clone()));restored.Original=entry.Original;restored.RestoreRows=factory.Select(x=>x.Clone()).ToList();restored.New=entry.New;restored.Dirty=true;Entries[Entries.IndexOf(entry)]=restored;return restored;}
 IEnumerable<TriggerRow> Output(TriggerEntry entry){if(entry.RestoreRows!=null)return entry.RestoreRows;if(!entry.Abbreviation)return new[]{new TriggerRow{Key=entry.Name,Value=entry.Replacement,Enabled=entry.Enabled,Exact=entry.Exact}};string unicode=entry.Replacement;return new[]{new TriggerRow{Key=entry.Name,Value=unicode,Enabled=entry.Enabled,Exact=entry.Exact},new TriggerRow{Key=entry.Name+">",Value=unicode,Enabled=entry.Enabled,Exact=entry.Exact},new TriggerRow{Key=entry.Name+"<",Value=entry.Exact?unicode:entry.LegacyOverride?entry.Legacy:EncodingMap.Balaram(unicode),Enabled=entry.Enabled,Exact=entry.Exact},new TriggerRow{Key=entry.Name+"?",Value=entry.Exact?unicode:entry.PlainOverride?entry.Plain:EncodingMap.Ascii(unicode),Enabled=entry.Enabled,Exact=entry.Exact}};}
 string Generate(TriggerEntry entry){var text=new StringBuilder();var json=new JavaScriptSerializer();foreach(var row in Output(entry)){text.Append("  - trigger: ").Append(json.Serialize(row.Key)).Append(newline).Append("    replace: ").Append(json.Serialize(row.Value)).Append(newline);if(!row.Enabled)text.Append("    enabled: false").Append(newline);if(row.Exact)text.Append("    keep_exact: true").Append(newline);}return text.ToString();}
 static string Comments(string text){var result=new StringBuilder();var lines=Regex.Matches(text,@"[^\r\n]+(?:\r?\n|$)").Cast<Match>().Select(x=>x.Value).ToArray();int indent=lines.Length==0?0:lines[0].TakeWhile(c=>c==' '||c=='\t').Count();foreach(string line in lines){string trim=line.TrimStart();if(trim.StartsWith("#")){result.Append(line);continue;}int leading=line.Length-trim.Length;if(leading>indent+2||!Regex.IsMatch(trim,@"^(?:-\s+trigger|replace|enabled|keep_exact):"))continue;bool single=false,doubled=false,escape=false;for(int i=0;i<line.Length;i++){char c=line[i];if(escape){escape=false;continue;}if(doubled&&c=='\\'){escape=true;continue;}if(c=='\''&&!doubled){if(single&&i+1<line.Length&&line[i+1]=='\''){i++;continue;}single=!single;continue;}if(c=='"'&&!single){doubled=!doubled;continue;}if(c=='#'&&!single&&!doubled&&i>0&&char.IsWhiteSpace(line[i-1])){result.Append(new string(' ',indent)).Append(line.Substring(i));break;}}}return result.ToString();}
 public string Render(){var text=new StringBuilder(header);var inserted=new HashSet<TriggerEntry>();foreach(var row in rows){var entry=Entries.First(x=>x.Original.Any(old=>old.Key==row.Key));if(!entry.Dirty){text.Append(row.Raw);continue;}if(!entry.Deleted&&inserted.Add(entry))text.Append(Generate(entry));text.Append(Comments(row.Raw));}foreach(var entry in Entries.Where(x=>x.New&&!x.Deleted&&!inserted.Contains(x)))text.Append(newline).Append(Generate(entry));string output=text.ToString();bool any=Entries.Any(x=>!x.Deleted);return any?Regex.Replace(output,@"(?m)^([ \t]*matches:)[ \t]*\[\]([ \t]*\r?)$","$1$2"):Regex.Replace(output,@"(?m)^([ \t]*matches:)([ \t]*\r?)$","$1 []$2");}
 static void WriteAtomic(string destination,byte[] bytes){Directory.CreateDirectory(Path.GetDirectoryName(destination));if(File.Exists(destination)&&(File.GetAttributes(destination)&FileAttributes.ReparsePoint)!=0)throw new IOException("A configuration file link cannot be replaced by the trigger editor.");string temporary=destination+".tmp-"+Guid.NewGuid().ToString("N");try{File.WriteAllBytes(temporary,bytes);SettingsFile.Commit(temporary,destination);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
 public void Save(Action apply){if(!File.ReadAllBytes(path).SequenceEqual(original))throw new IOException("The trigger file changed while this editor was open. Cancel and reopen it to keep those changes.");if(!Entries.Any(x=>x.Dirty))return;string text=Render();var utf8=new UTF8Encoding(bom);byte[] bytes=utf8.GetPreamble().Concat(utf8.GetBytes(text)).ToArray();string temporary=path+".tmp-"+Guid.NewGuid().ToString("N");try{File.WriteAllBytes(temporary,bytes);Configuration.Read(temporary,false,true);if(!File.ReadAllBytes(path).SequenceEqual(original))throw new IOException("The trigger file changed. Reopen the editor before saving.");string backup=Path.Combine(Directory.GetParent(Path.GetDirectoryName(path)).FullName,"backups","trigger-editor-previous.yml");WriteAtomic(backup,original);SettingsFile.Commit(temporary,path);try{if(apply!=null)apply();}catch{if(File.ReadAllBytes(path).SequenceEqual(bytes))WriteAtomic(path,original);throw;}}finally{if(File.Exists(temporary))File.Delete(temporary);}}
}
}
